def transform(grid):
    h, w = len(grid), len(grid[0])
    # A uniform center column divides two equal panels. Their common color is
    # the background; the distinct colors are marks to merge into one mask.
    sep = w // 2
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    lc = {v for row in left for v in row}
    rc = {v for row in right for v in row}
    shared = lc & rc
    if shared:
        bg = max(shared, key=lambda color: sum(v == color for row in left + right for v in row))
    else:
        bg = None
    return [[2 if left[r][c] != bg or right[r][c] != bg else 3
             for c in range(sep)] for r in range(h)]

if __name__ == '__main__':
    pass
